#[allow(missing_docs)]
/// Message in OmniPaxos. Can be either a `SequencePaxos` message (for log replication),
/// a `BLE` message (for leader election), or (when the `async_runtime` feature is enabled)
/// an `AsyncRuntime` message used by the actor layer for `append_notify` correlation.
#[derive(Clone, Debug)]
#[cfg_attr(feature = "serde", derive(Serialize, Deserialize))]
pub enum Message<T>
where
    T: Entry,
{
    SequencePaxos(PaxosMessage<T>),
    BLE(BLEMessage),
    #[cfg(feature = "async_runtime")]
    AsyncRuntime(AsyncRuntimeMessage<T>),
}

impl<T> Message<T>
where
    T: Entry,
{
    /// Get the sender id of the message
    pub fn get_sender(&self) -> NodeId {
        match self {
            Message::SequencePaxos(p) => p.from,
            Message::BLE(b) => b.from,
            #[cfg(feature = "async_runtime")]
            Message::AsyncRuntime(a) => a.from,
        }
    }

    /// Get the receiver id of the message
    pub fn get_receiver(&self) -> NodeId {
        match self {
            Message::SequencePaxos(p) => p.to,
            Message::BLE(b) => b.to,
            #[cfg(feature = "async_runtime")]
            Message::AsyncRuntime(a) => a.to,
        }
    }
}

/// Messages exchanged between actor instances for `append_notify` correlation.
/// These do not touch the core Paxos protocol — they run alongside it.
#[cfg(feature = "async_runtime")]
pub mod async_runtime {
    use crate::{ballot_leader_election::Ballot, storage::Entry, util::NodeId};
    #[cfg(feature = "serde")]
    use serde::{Deserialize, Serialize};

    /// A unique identifier for a tagged proposal, used to correlate a
    /// forwarded entry with its assigned log index.
    #[derive(Copy, Clone, Debug, Eq, PartialEq, Hash)]
    #[cfg_attr(feature = "serde", derive(Serialize, Deserialize))]
    pub struct EntryId(pub uuid::Uuid);

    /// Wrapper carrying sender/receiver for an [`AsyncRuntimeMsg`].
    #[derive(Clone, Debug)]
    #[cfg_attr(feature = "serde", derive(Serialize, Deserialize))]
    pub struct AsyncRuntimeMessage<T>
    where
        T: Entry,
    {
        /// Sender of `msg`.
        pub from: NodeId,
        /// Receiver of `msg`.
        pub to: NodeId,
        /// The runtime-message content.
        pub msg: AsyncRuntimeMsg<T>,
    }

    /// Runtime-layer messages used by the actor to correlate `append_notify` calls
    /// with the log index the leader eventually assigns.
    #[allow(missing_docs)]
    #[derive(Clone, Debug)]
    #[cfg_attr(feature = "serde", derive(Serialize, Deserialize))]
    pub enum AsyncRuntimeMsg<T>
    where
        T: Entry,
    {
        /// Follower actor → leader actor. Carries entries the originator(s) want
        /// tracked, batched into one message. Replaces the untagged
        /// `PaxosMsg::ProposalForward` path when the caller used `append_notify`.
        TaggedProposal { entries: Vec<(EntryId, T)> },
        /// Leader actor → originating follower actor. Carries, for each entry in a
        /// previously received `TaggedProposal` batch that was actually accepted,
        /// the log index the leader assigned, plus the single full ballot under
        /// which the *whole batch* was accepted (one ballot, not per-entry: the
        /// leader processes one incoming `TaggedProposal` synchronously with no
        /// yield points, so every entry in it is necessarily accepted under the
        /// same ballot).
        Assigned {
            ballot: Ballot,
            entries: Vec<(EntryId, usize)>,
        },
    }
}
