    pub(crate) fn forward_stopsign(&mut self, ss: StopSign) {
        let leader = self.get_current_leader();
        if leader > 0 && self.pid != leader {
            #[cfg(feature = "logging")]
            trace!(self.logger, "Forwarding StopSign to Leader {:?}", leader);
            let fs = PaxosMsg::ForwardStopSign(ss);
            let msg = Message::SequencePaxos(PaxosMessage {
                from: self.pid,
                to: leader,
                msg: fs,
            });
            self.outgoing.push(msg);
        } else if self.buffered_stopsign.as_mut().is_none() {
            self.buffered_stopsign = Some(ss);
        }
    }
    /// Returns `LogSync`, a struct to help other servers synchronize their log to correspond to the
    /// current state of our own log. The `common_prefix_idx` marks where in the log the other server
    /// needs to be sync from.
    fn create_log_sync(
        &self,
        common_prefix_idx: usize,
        other_logs_decided_idx: usize,
    ) -> LogSync<T> {
        let decided_idx = self.internal_storage.get_decided_idx();
        let (decided_snapshot, suffix, sync_idx) =
            if T::Snapshot::use_snapshots() && decided_idx > common_prefix_idx {
                // Note: We snapshot from the other log's decided index and not the common prefix because
                // snapshots currently only work on decided entries.
                let (delta_snapshot, compacted_idx) = self
                    .internal_storage
                    .create_diff_snapshot(other_logs_decided_idx)
                    .expect(READ_ERROR_MSG);
                let suffix = self
                    .internal_storage
                    .get_suffix(decided_idx)
                    .expect(READ_ERROR_MSG);
                (delta_snapshot, suffix, compacted_idx)
            } else {
                let suffix = self
                    .internal_storage
                    .get_suffix(common_prefix_idx)
                    .expect(READ_ERROR_MSG);
                (None, suffix, common_prefix_idx)
            };
        LogSync {
            decided_snapshot,
            suffix,
            sync_idx,
            stopsign: self.internal_storage.get_stopsign(),
        }
    }
}

#[derive(PartialEq, Debug)]
pub(crate) enum Phase {
    Prepare,
    Accept,
    Recover,
    None,
}

#[derive(PartialEq, Debug)]
pub(crate) enum Role {
    Follower,
    Leader,
}

/// Configuration for `SequencePaxos`.
/// # Fields
/// * `pid`: The unique identifier of this node. Must not be 0.
/// * `peers`: The peers of this node i.e. the `pid`s of the other servers in the configuration.
/// * `flexible_quorum` : Defines read and write quorum sizes. Can be used for different latency vs fault tolerance tradeoffs.
/// * `buffer_size`: The buffer size for outgoing messages.
/// * `batch_size`: The size of the buffer for log batching. The default is 1, which means no batching.
/// * `logger_file_path`: The path where the default logger logs events.
#[derive(Clone, Debug)]
pub(crate) struct SequencePaxosConfig {
    pid: NodeId,
    peers: Vec<NodeId>,
    buffer_size: usize,
    pub(crate) batch_size: usize,
    flexible_quorum: Option<FlexibleQuorum>,
    #[cfg(feature = "logging")]
    logger_file_path: Option<String>,
    #[cfg(feature = "logging")]
    custom_logger: Option<Logger>,
}

impl From<OmniPaxosConfig> for SequencePaxosConfig {
    fn from(config: OmniPaxosConfig) -> Self {
        let pid = config.server_config.pid;
        let peers = config
            .cluster_config
            .nodes
            .into_iter()
            .filter(|x| *x != pid)
            .collect();
        SequencePaxosConfig {
            pid,
            peers,
            flexible_quorum: config.cluster_config.flexible_quorum,
            buffer_size: config.server_config.buffer_size,
            batch_size: config.server_config.batch_size,
            #[cfg(feature = "logging")]
            logger_file_path: config.server_config.logger_file_path,
            #[cfg(feature = "logging")]
            custom_logger: config.server_config.custom_logger,
        }
    }
}
use super::super::{
    ballot_leader_election::Ballot,
    util::{LeaderState, PromiseMetaData},
};
use crate::util::{AcceptedMetaData, WRITE_ERROR_MSG};

use super::*;

impl<T, B> SequencePaxos<T, B>
where
    T: Entry,
    B: Storage<T>,
{
    /// Handle a new leader. Should be called when the leader election has elected a new leader with the ballot `n`
    /*** Leader ***/
    pub(crate) fn handle_leader(&mut self, n: Ballot) {
        if n <= self.leader_state.n_leader || n <= self.internal_storage.get_promise() {
            return;
        }
        #[cfg(feature = "logging")]
        debug!(self.logger, "Newly elected leader: {:?}", n);
        if self.pid == n.pid {
            self.leader_state =
                LeaderState::with(n, self.leader_state.max_pid, self.leader_state.quorum);
            // Flush any pending writes
            // Don't have to handle flushed entries here because we will sync with followers
            let _ = self.internal_storage.flush_batch().expect(WRITE_ERROR_MSG);
            self.internal_storage.set_promise(n).expect(WRITE_ERROR_MSG);
            /* insert my promise */
            let na = self.internal_storage.get_accepted_round();
            let decided_idx = self.get_decided_idx();
            let accepted_idx = self.internal_storage.get_accepted_idx();
            let my_promise = Promise {
                n,
                n_accepted: na,
                decided_idx,
                accepted_idx,
                log_sync: None,
            };
            self.leader_state.set_promise(my_promise, self.pid, true);
            /* initialise longest chosen sequence and update state */
            self.state = (Role::Leader, Phase::Prepare);
            let prep = Prepare {
                n,
                decided_idx,
                n_accepted: na,
                accepted_idx,
            };
            /* send prepare */
            for pid in &self.peers {
                self.outgoing.push(Message::SequencePaxos(PaxosMessage {
                    from: self.pid,
                    to: *pid,
                    msg: PaxosMsg::Prepare(prep),
                }));
            }
        } else {
            self.become_follower();
        }
    }

    pub(crate) fn become_follower(&mut self) {
        self.state.0 = Role::Follower;
    }

    pub(crate) fn handle_preparereq(&mut self, prepreq: PrepareReq, from: NodeId) {
        #[cfg(feature = "logging")]
        debug!(self.logger, "Incoming message PrepareReq from {}", from);
        if self.state.0 == Role::Leader && prepreq.n <= self.leader_state.n_leader {
            self.leader_state.reset_promise(from);
            self.leader_state.set_latest_accept_meta(from, None);
            self.send_prepare(from);
        }
    }

    pub(crate) fn handle_forwarded_proposal(&mut self, mut entries: Vec<T>) {
        if !self.accepted_reconfiguration() {
            match self.state {
                (Role::Leader, Phase::Prepare) => self.buffered_proposals.append(&mut entries),
                (Role::Leader, Phase::Accept) => self.accept_entries_leader(entries),
                _ => self.forward_proposals(entries),
            }
        }
    }

    pub(crate) fn handle_forwarded_stopsign(&mut self, ss: StopSign) {
        if self.accepted_reconfiguration() {
            return;
        }
        match self.state {
            (Role::Leader, Phase::Prepare) => self.buffered_stopsign = Some(ss),
            (Role::Leader, Phase::Accept) => self.accept_stopsign_leader(ss),
            _ => self.forward_stopsign(ss),
        }
    }

    pub(crate) fn send_prepare(&mut self, to: NodeId) {
        let prep = Prepare {
            n: self.leader_state.n_leader,
            decided_idx: self.internal_storage.get_decided_idx(),
            n_accepted: self.internal_storage.get_accepted_round(),
            accepted_idx: self.internal_storage.get_accepted_idx(),
        };
        self.outgoing.push(Message::SequencePaxos(PaxosMessage {
            from: self.pid,
            to,
            msg: PaxosMsg::Prepare(prep),
        }));
    }

    pub(crate) fn accept_entry_leader(&mut self, entry: T) {
        let accepted_metadata = self
            .internal_storage
            .append_entry_with_batching(entry)
            .expect(WRITE_ERROR_MSG);
        if let Some(metadata) = accepted_metadata {
            self.leader_state
                .set_accepted_idx(self.pid, metadata.accepted_idx);
            self.send_acceptdecide(metadata);
        }
    }

    pub(crate) fn accept_entries_leader(&mut self, entries: Vec<T>) {
        let accepted_metadata = self
            .internal_storage
            .append_entries_with_batching(entries)
            .expect(WRITE_ERROR_MSG);
        if let Some(metadata) = accepted_metadata {
            self.leader_state
                .set_accepted_idx(self.pid, metadata.accepted_idx);
            self.send_acceptdecide(metadata);
        }
    }

    pub(crate) fn accept_stopsign_leader(&mut self, ss: StopSign) {
        let accepted_metadata = self
            .internal_storage
            .append_stopsign(ss.clone())
            .expect(WRITE_ERROR_MSG);
        if let Some(metadata) = accepted_metadata {
            self.send_acceptdecide(metadata);
        }
        let accepted_idx = self.internal_storage.get_accepted_idx();
        self.leader_state.set_accepted_idx(self.pid, accepted_idx);
        for pid in self.leader_state.get_promised_followers() {
            self.send_accept_stopsign(pid, ss.clone(), false);
        }
    }

    fn send_accsync(&mut self, to: NodeId) {
        let current_n = self.leader_state.n_leader;
        let PromiseMetaData {
            n_accepted: prev_round_max_promise_n,
            accepted_idx: prev_round_max_accepted_idx,
            ..
        } = &self.leader_state.get_max_promise_meta();
        let PromiseMetaData {
            n_accepted: followers_promise_n,
            accepted_idx: followers_accepted_idx,
            pid,
            ..
        } = self.leader_state.get_promise_meta(to);
        let followers_decided_idx = self
            .leader_state
            .get_decided_idx(*pid)
            .expect("Received PromiseMetaData but not found in ld");
        // Follower can have valid accepted entries depending on which leader they were previously following
        let followers_valid_entries_idx = if *followers_promise_n == current_n {
            *followers_accepted_idx
        } else if *followers_promise_n == *prev_round_max_promise_n {
            *prev_round_max_accepted_idx.min(followers_accepted_idx)
        } else {
            followers_decided_idx
        };
        let log_sync = self.create_log_sync(followers_valid_entries_idx, followers_decided_idx);
        self.leader_state.increment_seq_num_session(to);
        let acc_sync = AcceptSync {
            n: current_n,
            seq_num: self.leader_state.next_seq_num(to),
            decided_idx: self.get_decided_idx(),
            log_sync,
            #[cfg(feature = "unicache")]
            unicache: self.internal_storage.get_unicache(),
        };
        let msg = Message::SequencePaxos(PaxosMessage {
            from: self.pid,
            to,
            msg: PaxosMsg::AcceptSync(acc_sync),
        });
        self.outgoing.push(msg);
    }

    fn send_acceptdecide(&mut self, accepted: AcceptedMetaData<T>) {
        let decided_idx = self.internal_storage.get_decided_idx();
        for pid in self.leader_state.get_promised_followers() {
            let latest_accdec = self.get_latest_accdec_message(pid);
            match latest_accdec {
                // Modify existing AcceptDecide message to follower
                Some(accdec) => {
                    accdec.entries.extend(accepted.entries.iter().cloned());
                    accdec.decided_idx = decided_idx;
                }
                // Add new AcceptDecide message to follower
                None => {
                    self.leader_state
                        .set_latest_accept_meta(pid, Some(self.outgoing.len()));
                    let acc = AcceptDecide {
                        n: self.leader_state.n_leader,
                        seq_num: self.leader_state.next_seq_num(pid),
                        decided_idx,
                        entries: accepted.entries.clone(),
                    };
                    self.outgoing.push(Message::SequencePaxos(PaxosMessage {
                        from: self.pid,
                        to: pid,
                        msg: PaxosMsg::AcceptDecide(acc),
                    }));
                }
            }
        }
    }

    fn send_accept_stopsign(&mut self, to: NodeId, ss: StopSign, resend: bool) {
        let seq_num = match resend {
            true => self.leader_state.get_seq_num(to),
            false => self.leader_state.next_seq_num(to),
        };
        let acc_ss = PaxosMsg::AcceptStopSign(AcceptStopSign {
            seq_num,
            n: self.leader_state.n_leader,
            ss,
        });
        self.outgoing.push(Message::SequencePaxos(PaxosMessage {
            from: self.pid,
            to,
            msg: acc_ss,
        }));
    }

    pub(crate) fn send_decide(&mut self, to: NodeId, decided_idx: usize, resend: bool) {
        let seq_num = match resend {
            true => self.leader_state.get_seq_num(to),
            false => self.leader_state.next_seq_num(to),
        };
        let d = Decide {
            n: self.leader_state.n_leader,
            seq_num,
            decided_idx,
        };
        self.outgoing.push(Message::SequencePaxos(PaxosMessage {
            from: self.pid,
            to,
            msg: PaxosMsg::Decide(d),
        }));
    }

    fn handle_majority_promises(&mut self) {
        let max_promise_sync = self.leader_state.take_max_promise_sync();
        let decided_idx = self.leader_state.get_max_decided_idx();
        let mut new_accepted_idx = self
            .internal_storage
            .sync_log(self.leader_state.n_leader, decided_idx, max_promise_sync)
            .expect(WRITE_ERROR_MSG);
        if !self.accepted_reconfiguration() {
            if !self.buffered_proposals.is_empty() {
                let entries = std::mem::take(&mut self.buffered_proposals);
                new_accepted_idx = self
                    .internal_storage
                    .append_entries_without_batching(entries)
                    .expect(WRITE_ERROR_MSG);
            }
            if let Some(ss) = self.buffered_stopsign.take() {
                self.internal_storage
                    .append_stopsign(ss)
                    .expect(WRITE_ERROR_MSG);
                new_accepted_idx = self.internal_storage.get_accepted_idx();
            }
        }
        self.state = (Role::Leader, Phase::Accept);
        self.leader_state
            .set_accepted_idx(self.pid, new_accepted_idx);
        for pid in self.leader_state.get_promised_followers() {
            self.send_accsync(pid);
        }
    }

    pub(crate) fn handle_promise_prepare(&mut self, prom: Promise<T>, from: NodeId) {
        #[cfg(feature = "logging")]
        debug!(
            self.logger,
            "Handling promise from {} in Prepare phase", from
        );
        if prom.n == self.leader_state.n_leader {
            let received_majority = self.leader_state.set_promise(prom, from, true);
            if received_majority {
                self.handle_majority_promises();
            }
        }
    }

    pub(crate) fn handle_promise_accept(&mut self, prom: Promise<T>, from: NodeId) {
        #[cfg(feature = "logging")]
        {
            let (r, p) = &self.state;
            debug!(
                self.logger,
                "Self role {:?}, phase {:?}. Incoming message Promise Accept from {}", r, p, from
            );
        }
        if prom.n == self.leader_state.n_leader {
            self.leader_state.set_promise(prom, from, false);
            self.send_accsync(from);
        }
    }

    pub(crate) fn handle_accepted(&mut self, accepted: Accepted, from: NodeId) {
        #[cfg(feature = "logging")]
        trace!(
            self.logger,
            "Got Accepted from {}, idx: {}, chosen_idx: {}, accepted: {:?}",
            from,
            accepted.accepted_idx,
            self.internal_storage.get_decided_idx(),
            self.leader_state.accepted_indexes
        );
        if accepted.n == self.leader_state.n_leader && self.state == (Role::Leader, Phase::Accept) {
            self.leader_state
                .set_accepted_idx(from, accepted.accepted_idx);
            if accepted.accepted_idx > self.internal_storage.get_decided_idx()
                && self.leader_state.is_chosen(accepted.accepted_idx)
            {
                let decided_idx = accepted.accepted_idx;
                self.internal_storage
                    .set_decided_idx(decided_idx)
                    .expect(WRITE_ERROR_MSG);
                for pid in self.leader_state.get_promised_followers() {
                    let latest_accdec = self.get_latest_accdec_message(pid);
                    match latest_accdec {
                        Some(accdec) => accdec.decided_idx = decided_idx,
                        None => self.send_decide(pid, decided_idx, false),
                    }
                }
            }
        }
    }

    fn get_latest_accdec_message(&mut self, to: NodeId) -> Option<&mut AcceptDecide<T>> {
        if let Some((bal, outgoing_idx)) = self.leader_state.get_latest_accept_meta(to) {
            if bal == self.leader_state.n_leader {
                if let Message::SequencePaxos(PaxosMessage {
                    msg: PaxosMsg::AcceptDecide(accdec),
                    ..
                }) = self.outgoing.get_mut(outgoing_idx).unwrap()
                {
                    return Some(accdec);
                } else {
                    #[cfg(feature = "logging")]
                    debug!(self.logger, "Cached idx is not an AcceptedDecide!");
                }
            }
        }
        None
    }

    pub(crate) fn handle_notaccepted(&mut self, not_acc: NotAccepted, from: NodeId) {
        if self.state.0 == Role::Leader && self.leader_state.n_leader < not_acc.n {
            self.leader_state.lost_promise(from);
        }
    }

    pub(crate) fn resend_messages_leader(&mut self) {
        match self.state.1 {
            Phase::Prepare => {
                // Resend Prepare
                let preparable_peers = self.leader_state.get_preparable_peers(&self.peers);
                for peer in preparable_peers {
                    self.send_prepare(peer);
                }
            }
            Phase::Accept => {
                // Resend AcceptStopSign or StopSign's decide
                if let Some(ss) = self.internal_storage.get_stopsign() {
                    let decided_idx = self.internal_storage.get_decided_idx();
                    for follower in self.leader_state.get_promised_followers() {
                        if self.internal_storage.stopsign_is_decided() {
                            self.send_decide(follower, decided_idx, true);
                        } else if self.leader_state.get_accepted_idx(follower)
                            != self.internal_storage.get_accepted_idx()
                        {
                            self.send_accept_stopsign(follower, ss.clone(), true);
                        }
                    }
                }
                // Resend Prepare
                let preparable_peers = self.leader_state.get_preparable_peers(&self.peers);
                for peer in preparable_peers {
                    self.send_prepare(peer);
                }
            }
            Phase::Recover => (),
            Phase::None => (),
        }
    }

    pub(crate) fn flush_batch_leader(&mut self) {
        let accepted_metadata = self
            .internal_storage
            .flush_batch_and_get_entries()
            .expect(WRITE_ERROR_MSG);
        if let Some(metadata) = accepted_metadata {
            self.leader_state
                .set_accepted_idx(self.pid, metadata.accepted_idx);
            self.send_acceptdecide(metadata);
        }
    }
}

use super::super::ballot_leader_election::Ballot;

use super::*;

use crate::util::{MessageStatus, WRITE_ERROR_MSG};

impl<T, B> SequencePaxos<T, B>
where
    T: Entry,
    B: Storage<T>,
{
    /*** Follower ***/
    pub(crate) fn handle_prepare(&mut self, prep: Prepare, from: NodeId) {
        let old_promise = self.internal_storage.get_promise();
        if old_promise < prep.n || (old_promise == prep.n && self.state.1 == Phase::Recover) {
            // Flush any pending writes
            // Don't have to handle flushed entries here because we will sync with followers
            let _ = self.internal_storage.flush_batch().expect(WRITE_ERROR_MSG);
            self.internal_storage
                .set_promise(prep.n)
                .expect(WRITE_ERROR_MSG);
            self.state = (Role::Follower, Phase::Prepare);
            self.current_seq_num = SequenceNumber::default();
            let na = self.internal_storage.get_accepted_round();
            let accepted_idx = self.internal_storage.get_accepted_idx();
            let log_sync = if na > prep.n_accepted {
                // I'm more up to date: send leader what he is missing after his decided index.
                Some(self.create_log_sync(prep.decided_idx, prep.decided_idx))
            } else if na == prep.n_accepted && accepted_idx > prep.accepted_idx {
                // I'm more up to date and in same round: send leader what he is missing after his
                // accepted index.
                Some(self.create_log_sync(prep.accepted_idx, prep.decided_idx))
            } else {
                // I'm equally or less up to date
                None
            };
            let promise = Promise {
                n: prep.n,
                n_accepted: na,
                decided_idx: self.internal_storage.get_decided_idx(),
                accepted_idx,
                log_sync,
            };
            self.cached_promise_message = Some(promise.clone());
            self.outgoing.push(Message::SequencePaxos(PaxosMessage {
                from: self.pid,
                to: from,
                msg: PaxosMsg::Promise(promise),
            }));
        }
    }

    pub(crate) fn handle_acceptsync(&mut self, accsync: AcceptSync<T>, from: NodeId) {
        if self.check_valid_ballot(accsync.n) && self.state == (Role::Follower, Phase::Prepare) {
            self.cached_promise_message = None;
            let new_accepted_idx = self
                .internal_storage
                .sync_log(accsync.n, accsync.decided_idx, Some(accsync.log_sync))
                .expect(WRITE_ERROR_MSG);
            if self.internal_storage.get_stopsign().is_none() {
                self.forward_buffered_proposals();
            }
            let accepted = Accepted {
                n: accsync.n,
                accepted_idx: new_accepted_idx,
            };
            self.state = (Role::Follower, Phase::Accept);
            self.current_seq_num = accsync.seq_num;
            let cached_idx = self.outgoing.len();
            self.latest_accepted_meta = Some((accsync.n, cached_idx));
            self.outgoing.push(Message::SequencePaxos(PaxosMessage {
                from: self.pid,
                to: from,
                msg: PaxosMsg::Accepted(accepted),
            }));
            #[cfg(feature = "unicache")]
            self.internal_storage.set_unicache(accsync.unicache);
        }
    }

    fn forward_buffered_proposals(&mut self) {
        let proposals = std::mem::take(&mut self.buffered_proposals);
        if !proposals.is_empty() {
            self.forward_proposals(proposals);
        }
    }

    pub(crate) fn handle_acceptdecide(&mut self, acc_dec: AcceptDecide<T>) {
        if self.check_valid_ballot(acc_dec.n)
            && self.state == (Role::Follower, Phase::Accept)
            && self.handle_sequence_num(acc_dec.seq_num, acc_dec.n.pid) == MessageStatus::Expected
        {
            #[cfg(not(feature = "unicache"))]
            let entries = acc_dec.entries;
            #[cfg(feature = "unicache")]
            let entries = self.internal_storage.decode_entries(acc_dec.entries);
            let mut new_accepted_idx = self
                .internal_storage
                .append_entries_and_get_accepted_idx(entries)
                .expect(WRITE_ERROR_MSG);
            let flushed_after_decide =
                self.update_decided_idx_and_get_accepted_idx(acc_dec.decided_idx);
            if flushed_after_decide.is_some() {
                new_accepted_idx = flushed_after_decide;
            }
            if let Some(idx) = new_accepted_idx {
                self.reply_accepted(acc_dec.n, idx);
            }
        }
    }

    pub(crate) fn handle_accept_stopsign(&mut self, acc_ss: AcceptStopSign) {
        if self.check_valid_ballot(acc_ss.n)
            && self.state == (Role::Follower, Phase::Accept)
            && self.handle_sequence_num(acc_ss.seq_num, acc_ss.n.pid) == MessageStatus::Expected
        {
            // Flush entries before appending stopsign. The accepted index is ignored here as
            // it will be updated when appending stopsign.
            let _ = self.internal_storage.flush_batch().expect(WRITE_ERROR_MSG);
            let new_accepted_idx = self
                .internal_storage
                .set_stopsign(Some(acc_ss.ss))
                .expect(WRITE_ERROR_MSG);
            self.reply_accepted(acc_ss.n, new_accepted_idx);
        }
    }

    pub(crate) fn handle_decide(&mut self, dec: Decide) {
        if self.check_valid_ballot(dec.n)
            && self.state.1 == Phase::Accept
            && self.handle_sequence_num(dec.seq_num, dec.n.pid) == MessageStatus::Expected
        {
            let new_accepted_idx = self.update_decided_idx_and_get_accepted_idx(dec.decided_idx);
            if let Some(idx) = new_accepted_idx {
                self.reply_accepted(dec.n, idx);
            }
        }
    }

    /// To maintain decided index <= accepted index, batched entries may be flushed.
    /// Returns `Some(new_accepted_idx)` if entries are flushed, otherwise `None`.
    fn update_decided_idx_and_get_accepted_idx(&mut self, new_decided_idx: usize) -> Option<usize> {
        if new_decided_idx <= self.internal_storage.get_decided_idx() {
            return None;
        }
        if new_decided_idx > self.internal_storage.get_accepted_idx() {
            let new_accepted_idx = self.internal_storage.flush_batch().expect(WRITE_ERROR_MSG);
            self.internal_storage
                .set_decided_idx(new_decided_idx.min(new_accepted_idx))
                .expect(WRITE_ERROR_MSG);
            Some(new_accepted_idx)
        } else {
            self.internal_storage
                .set_decided_idx(new_decided_idx)
                .expect(WRITE_ERROR_MSG);
            None
        }
    }

    fn reply_accepted(&mut self, n: Ballot, accepted_idx: usize) {
        let latest_accepted = self.get_latest_accepted_message(n);
        match latest_accepted {
            Some(acc) => acc.accepted_idx = accepted_idx,
            None => {
                let accepted = Accepted { n, accepted_idx };
                let cached_idx = self.outgoing.len();
                self.latest_accepted_meta = Some((n, cached_idx));
                self.outgoing.push(Message::SequencePaxos(PaxosMessage {
                    from: self.pid,
                    to: n.pid,
                    msg: PaxosMsg::Accepted(accepted),
                }));
            }
        }
    }

    fn get_latest_accepted_message(&mut self, n: Ballot) -> Option<&mut Accepted> {
        if let Some((ballot, outgoing_idx)) = &self.latest_accepted_meta {
            if *ballot == n {
                if let Message::SequencePaxos(PaxosMessage {
                    msg: PaxosMsg::Accepted(a),
                    ..
                }) = self.outgoing.get_mut(*outgoing_idx).unwrap()
                {
                    return Some(a);
                } else {
                    #[cfg(feature = "logging")]
                    debug!(self.logger, "Cached idx is not an Accepted message!");
                }
            }
        }
        None
    }

    /// Also returns whether the message's ballot was promised
    fn check_valid_ballot(&mut self, message_ballot: Ballot) -> bool {
        let my_promise = self.internal_storage.get_promise();
        match my_promise.cmp(&message_ballot) {
            std::cmp::Ordering::Equal => true,
            std::cmp::Ordering::Greater => {
                let not_acc = NotAccepted { n: my_promise };
                #[cfg(feature = "logging")]
                trace!(
                    self.logger,
                    "NotAccepted. My promise: {:?}, theirs: {:?}",
                    my_promise,
                    message_ballot
                );
                self.outgoing.push(Message::SequencePaxos(PaxosMessage {
                    from: self.pid,
                    to: message_ballot.pid,
                    msg: PaxosMsg::NotAccepted(not_acc),
                }));
                false
            }
            std::cmp::Ordering::Less => {
                // Should never happen, but to be safe send PrepareReq
                #[cfg(feature = "logging")]
                warn!(
                    self.logger,
                    "Received non-prepare message from a leader I've never promised. My: {:?}, theirs: {:?}", my_promise, message_ballot
                );
                self.reconnected(message_ballot.pid);
                false
            }
        }
    }

    /// Also returns the MessageStatus of the sequence based on the incoming sequence number.
    fn handle_sequence_num(&mut self, seq_num: SequenceNumber, from: NodeId) -> MessageStatus {
        let msg_status = self.current_seq_num.check_msg_status(seq_num);
        match msg_status {
            MessageStatus::Expected => self.current_seq_num = seq_num,
            MessageStatus::DroppedPreceding => self.reconnected(from),
            MessageStatus::Outdated => (),
        };
        msg_status
    }

    pub(crate) fn resend_messages_follower(&mut self) {
        match self.state.1 {
            Phase::Prepare => {
                // Resend Promise
                match &self.cached_promise_message {
                    Some(promise) => {
                        self.outgoing.push(Message::SequencePaxos(PaxosMessage {
                            from: self.pid,
                            to: promise.n.pid,
                            msg: PaxosMsg::Promise(promise.clone()),
                        }));
                    }
                    None => {
                        // Shouldn't be possible to be in prepare phase without having
                        // cached the promise sent as a response to the prepare
                        #[cfg(feature = "logging")]
                        warn!(self.logger, "In Prepare phase without a cached promise!");
                        self.state = (Role::Follower, Phase::Recover);
                        self.send_preparereq_to_all_peers();
                    }
                }
            }
            Phase::Recover => {
                // Resend PrepareReq
                self.send_preparereq_to_all_peers();
            }
            Phase::Accept => (),
            Phase::None => (),
        }
    }

    fn send_preparereq_to_all_peers(&mut self) {
        let prepreq = PrepareReq {
            n: self.get_promise(),
        };
        for peer in &self.peers {
            self.outgoing.push(Message::SequencePaxos(PaxosMessage {
                from: self.pid,
                to: *peer,
                msg: PaxosMsg::PrepareReq(prepreq),
            }));
        }
    }

    pub(crate) fn flush_batch_follower(&mut self) {
        let accepted_idx = self.internal_storage.get_accepted_idx();
        let new_accepted_idx = self.internal_storage.flush_batch().expect(WRITE_ERROR_MSG);
        if new_accepted_idx > accepted_idx {
            self.reply_accepted(self.get_promise(), new_accepted_idx);
        }
    }
}

use core::time::Duration;
use std::{
    collections::{HashMap, VecDeque},
    marker::PhantomData,
    time::Instant,
};

use futures::{channel::oneshot, select_biased, FutureExt, StreamExt};

use omnipaxos::{
    ballot_leader_election::Ballot,
    messages::{
        async_runtime::{AsyncRuntimeMessage, AsyncRuntimeMsg, EntryId},
        Message,
    },
    storage::{Entry, Storage},
    util::{LogEntry, NodeId},
    OmniPaxos, ProposeErr,
};

use super::{
    event::{AppendError, Command, OmniPaxosEvent},
    handle::RuntimeConfig,
    traits::{ActorEntry, AsyncRuntime},
};

/// Actor-loop-relevant subset of [`RuntimeConfig`]. Excludes the channel-capacity
/// fields, which are only needed once, to construct the channels in `spawn_actor`
/// before the actor itself is built — mirrors how `SequencePaxosConfig` in the core
/// crate trims down the public `OmniPaxosConfig` to just what that component needs.
pub(crate) struct ActorConfig {
    tick_period: Duration,
    egress_period: Duration,
    append_notify_timeout: Duration,
    max_pending_appends: usize,
    max_decided_subscribers: usize,
    max_outgoing_buffered: usize,
}

impl From<&RuntimeConfig> for ActorConfig {
    fn from(cfg: &RuntimeConfig) -> Self {
        Self {
            tick_period: cfg.tick_period,
            egress_period: cfg.egress_period,
            append_notify_timeout: cfg.append_notify_timeout,
            max_pending_appends: cfg.max_pending_appends,
            max_decided_subscribers: cfg.max_decided_subscribers,
            max_outgoing_buffered: cfg.max_outgoing_buffered,
        }
    }
}

/// A pending `append_notify` awaiting decision. Uniform representation regardless
/// of whether the entry was accepted locally (we are leader) or forwarded (we are
/// follower). The `assigned` field is filled in by either code path; the drain
/// loop treats every pending item the same way.
struct Pending<T>
where
    T: Entry,
{
    id: EntryId,
    /// The entry, retained until dispatched (accepted locally or sent as a
    /// `TaggedProposal`). While `Some`, `try_dispatch_undispatched` retries it
    /// each tick — this is what lets `append_notify` be called before a
    /// leader is known.
    undispatched: Option<T>,
    /// `(assigned_idx, ballot_at_assignment)`. `None` until either:
    ///   (a) we accepted the entry ourselves as leader, or
    ///   (b) we received `AsyncRuntimeMsg::Assigned` from the leader.
    assigned: Option<(usize, Ballot)>,
    deadline: Instant,
    reply: oneshot::Sender<Result<usize, AppendError<T>>>,
}

/// What to do, once its index is known, for a write buffered in the shared
/// batch buffer. Every code path that can add to that buffer pushes one of
/// these (see `track_untracked_batch_growth`), keeping `unconfirmed_local`'s
/// FIFO position in sync with the buffer regardless of source.
enum TrackIntent {
    /// Not tracked: a plain `Command::Append`, or an entry that entered the
    /// buffer via core-internal protocol handling we have no id for (a
    /// forwarded proposal, replicated entries, a reconfiguration stopsign).
    Untracked,
    /// Resolve a pending `append_notify` we own directly, via `self.pending`,
    /// once this index is known.
    Local(EntryId),
    /// Reply with `AsyncRuntimeMsg::Assigned` to `from` once this index is
    /// known -- used for entries that arrived via a remote `TaggedProposal`
    /// and got deferred by batching rather than accepted immediately (the
    /// immediate case is handled inline by `handle_runtime_msg` instead).
    Remote { id: EntryId, from: NodeId },
}

pub(crate) struct ActorState<T, B>
where
    T: Entry,
    B: Storage<T>,
{
    pub(crate) op: OmniPaxos<T, B>,
    pub(crate) cmd_rx: async_channel::Receiver<Command<T>>,
    pub(crate) incoming_rx: async_channel::Receiver<Message<T>>,
    pub(crate) outgoing_tx: async_channel::Sender<Message<T>>,
    pub(crate) event_tx: async_channel::Sender<OmniPaxosEvent>,
    pub(crate) config: ActorConfig,

    pid: NodeId,
    outgoing_buf: Vec<Message<T>>,
    pending: VecDeque<Pending<T>>,
    decided_subscribers: Vec<DecidedSub<T>>,
    last_leader: Option<(NodeId, bool)>,
    last_decided_idx: usize,
    last_reconfigured: bool,
    /// One entry per write currently sitting in the shared per-node batch
    /// buffer, in the order it was added, awaiting the flush that assigns it
    /// an index. Popping one entry per unit of `get_accepted_idx()` advance
    /// (`reconcile_unconfirmed`) lines up with what actually flushed. Paired
    /// with the ballot in effect when buffered so a leader change before the
    /// flush is detected rather than mis-assigned.
    unconfirmed_local: VecDeque<(TrackIntent, Ballot)>,
    last_seen_accepted_idx: usize,
}

/// A single subscriber to the decided-log stream. `next_idx` is the next log
/// index the actor must deliver; incremented on every successful `try_send`.
struct DecidedSub<T>
where
    T: Entry,
{
    next_idx: usize,
    tx: async_channel::Sender<LogEntry<T>>,
}

impl<T, B> ActorState<T, B>
where
    T: Entry,
    B: Storage<T>,
{
    pub(crate) fn new(
        op: OmniPaxos<T, B>,
        cmd_rx: async_channel::Receiver<Command<T>>,
        incoming_rx: async_channel::Receiver<Message<T>>,
        outgoing_tx: async_channel::Sender<Message<T>>,
        event_tx: async_channel::Sender<OmniPaxosEvent>,
        config: ActorConfig,
    ) -> Self {
        let last_decided_idx = op.get_decided_idx();
        let last_leader = op.get_current_leader();
        let pid = op.get_pid();
        let accepted_idx = op.get_accepted_idx();
        Self {
            op,
            cmd_rx,
            incoming_rx,
            outgoing_tx,
            event_tx,
            config,
            pid,
            outgoing_buf: Vec::new(),
            pending: VecDeque::new(),
            decided_subscribers: Vec::new(),
            last_leader,
            last_decided_idx,
            last_reconfigured: false,
            unconfirmed_local: VecDeque::new(),
            last_seen_accepted_idx: accepted_idx,
        }
    }

    async fn detect_and_emit_events(&mut self) {
        let cur = self.op.get_current_leader();
        if cur != self.last_leader {
            if let Some((pid, accepted)) = cur {
                let _ = self
                    .event_tx
                    .send(OmniPaxosEvent::LeaderElected { pid, accepted })
                    .await;
            }
            self.last_leader = cur;
        }
        let d = self.op.get_decided_idx();
        if d > self.last_decided_idx {
            let _ = self
                .event_tx
                .send(OmniPaxosEvent::Decided { new_decided_idx: d })
                .await;
            self.last_decided_idx = d;
        }
        if !self.last_reconfigured {
            if let Some(_ss) = self.op.is_reconfigured() {
                let _ = self
                    .event_tx
                    .send(OmniPaxosEvent::Reconfigured {
                        stop_sign_idx: self.op.get_decided_idx(),
                    })
                    .await;
                self.last_reconfigured = true;
            }
        }
    }

    fn drain_notifiers(&mut self) {
        let decided = self.op.get_decided_idx();
        let now = Instant::now();
        let cur_ballot = self.op.get_promise();
        let old = std::mem::take(&mut self.pending);
        for p in old {
            match p.assigned {
                Some((idx, _)) if idx <= decided => {
                    let _ = p.reply.send(Ok(idx));
                }
                Some((idx, ballot)) if ballot < cur_ballot => {
                    let _ = p
                        .reply
                        .send(Err(AppendError::Superseded { log_entry_idx: idx }));
                }
                _ if now > p.deadline => {
                    let _ = p.reply.send(Err(AppendError::Timeout));
                }
                _ => self.pending.push_back(p),
            }
        }
    }

    /// Effective cap for `outgoing_buf`: the channel's own capacity when known,
    /// else [`ActorConfig::max_outgoing_buffered`].
    fn outgoing_buf_cap(&self) -> usize {
        self.outgoing_tx
            .capacity()
            .unwrap_or(self.config.max_outgoing_buffered)
    }

    /// Non-blocking drain of `outgoing_buf` onto `outgoing_tx`. Uses `try_send`
    /// so a merely-full channel (slow consumer) doesn't block the actor loop;
    /// unsent messages stay in `outgoing_buf` (in order) for the next attempt.
    /// If the buffer exceeds [`Self::outgoing_buf_cap`], oldest messages are
    /// dropped — see [`RuntimeConfig::max_outgoing_buffered`].
    fn drain_outgoing_buf(&mut self) {
        let cap = self.outgoing_buf_cap();
        trim_oldest(&mut self.outgoing_buf, cap);

        let pending = std::mem::take(&mut self.outgoing_buf);
        let mut iter = pending.into_iter();
        for msg in iter.by_ref() {
            match self.outgoing_tx.try_send(msg) {
                Ok(()) => {}
                Err(async_channel::TrySendError::Full(msg)) => {
                    self.outgoing_buf.push(msg);
                    break;
                }
                Err(async_channel::TrySendError::Closed(_)) => {
                    // Receiver dropped — user is not draining outgoing. Discard
                    // everything remaining; nothing left to retry against.
                    return;
                }
            }
        }
        self.outgoing_buf.extend(iter);
    }

    /// Enqueue one outgoing message without awaiting. Appends behind any
    /// already-buffered messages (preserves order), then tries to drain.
    /// Used for both core protocol traffic (via [`Self::flush_outgoing`]) and
    /// runtime control-plane messages (`TaggedProposal` / `Assigned`).
    fn enqueue_outgoing(&mut self, msg: Message<T>) {
        self.outgoing_buf.push(msg);
        self.drain_outgoing_buf();
    }

    /// Pull newly-produced OmniPaxos/BLE messages into `outgoing_buf` and drain.
    fn flush_outgoing(&mut self) {
        self.op.take_outgoing_messages(&mut self.outgoing_buf);
        self.drain_outgoing_buf();
    }

    /// Push newly-decided entries to a single, freshly-added subscriber. Used
    /// only on the immediate catch-up path from `Command::SubscribeDecided`,
    /// where there is no shared read to amortize against. Returns `false` if
    /// the receiver was already closed.
    fn push_to_sub(op: &mut OmniPaxos<T, B>, sub: &mut DecidedSub<T>) -> bool {
        let decided = op.get_decided_idx();
        if sub.next_idx >= decided {
            return true;
        }
        let Some(entries) = op.read_decided_suffix(sub.next_idx) else {
            return true;
        };
        for entry in entries {
            match sub.tx.try_send(entry) {
                Ok(()) => sub.next_idx += 1,
                Err(async_channel::TrySendError::Full(_)) => return true,
                Err(async_channel::TrySendError::Closed(_)) => return false,
            }
        }
        true
    }

    /// Push newly-decided entries to every subscriber, reading the log suffix
    /// **once** and fanning out. Each sub keeps its own cursor, so slow subs
    /// don't block fast ones; the storage read is amortized across all subs
    /// starting from the trailing sub's position.
    fn push_to_all_subs(&mut self) {
        if self.decided_subscribers.is_empty() {
            return;
        }
        let cur = self.op.get_decided_idx();
        let min_next = self
            .decided_subscribers
            .iter()
            .map(|s| s.next_idx)
            .min()
            .expect("non-empty checked above");
        if min_next >= cur {
            return;
        }
        // Read once, from the trailing sub's position. `entries[i]` is the log
        // entry at position `min_next + i`.
        let Some(entries) = self.op.read_decided_suffix(min_next) else {
            return;
        };
        // Fan out; drop closed subscribers in place via retain_mut.
        self.decided_subscribers.retain_mut(|sub| {
            // sub.next_idx should always be >= min_next; guard defensively.
            let start = sub.next_idx.saturating_sub(min_next);
            for entry in entries.iter().skip(start) {
                match sub.tx.try_send(entry.clone()) {
                    Ok(()) => sub.next_idx += 1,
                    Err(async_channel::TrySendError::Full(_)) => break,
                    Err(async_channel::TrySendError::Closed(_)) => return false,
                }
            }
            true
        });
    }

    fn record_assignment(&mut self, id: EntryId, idx: usize, ballot: Ballot) {
        for p in self.pending.iter_mut() {
            if p.id == id {
                p.assigned = Some((idx, ballot));
                return;
            }
        }
        // No matching pending — late reply after timeout drain, or duplicate. Ignore.
    }

    /// Resolves a pending `append_notify` immediately with the propose error that
    /// just failed it, instead of leaving it to silently time out. Only affects
    /// entries this node itself owns in `self.pending` — when `id` came from a
    /// remote `TaggedProposal`, the owning `Pending` lives on the origin node, so
    /// this is a no-op there and that call still resolves via `Timeout`.
    fn resolve_pending_failed(&mut self, id: EntryId, err: ProposeErr<T>) {
        if let Some(pos) = self.pending.iter().position(|p| p.id == id) {
            let p = self.pending.remove(pos).unwrap();
            let _ = p.reply.send(Err(AppendError::Propose(err)));
        }
    }

    /// Appends `entry` to the local log, tracking it in `unconfirmed_local` if
    /// the write is genuinely deferred by batching (`get_batched_len()` grew)
    /// rather than immediately reflected in `get_accepted_idx()`. `intent`
    /// says what to do with the eventual index; plain `Command::Append` passes
    /// `TrackIntent::Untracked`.
    ///
    /// Must check `get_batched_len()` rather than inferring "batched" from
    /// `before == after`: a follower, or a leader still in `Phase::Prepare`,
    /// also has `before == after`, but the entry went to `buffered_proposals`
    /// or out as a `ProposalForward`, not the shared batch buffer — pushing a
    /// placeholder for that case would desync `unconfirmed_local`'s FIFO
    /// count. `accept_as_leader`'s stable-leader gate means only plain
    /// `Command::Append` can hit this case.
    fn append_tracked(
        &mut self,
        intent: TrackIntent,
        entry: T,
    ) -> Result<Option<(usize, Ballot)>, ProposeErr<T>> {
        let accepted_before = self.op.get_accepted_idx();
        let batched_before = self.op.get_batched_len();
        self.op.append(entry)?;
        let accepted_after = self.op.get_accepted_idx();
        let batched_after = self.op.get_batched_len();
        if accepted_after > accepted_before {
            let ballot = self.op.get_promise();
            if let TrackIntent::Local(id) = intent {
                self.record_assignment(id, accepted_after, ballot);
            }
            Ok(Some((accepted_after, ballot)))
        } else if batched_after > batched_before {
            // Genuinely deferred by batching.
            self.unconfirmed_local
                .push_back((intent, self.op.get_promise()));
            Ok(None)
        } else {
            // Went somewhere else entirely (forwarded, or buffered pending a
            // Prepare -> Accept transition) -- nothing entered the shared
            // batch buffer, so there's nothing to track here.
            Ok(None)
        }
    }

    /// Leader-side accept, for an entry we originate locally (`from: None`)
    /// or received via `TaggedProposal` from follower `from`. Populates the
    /// pending's `assigned` (or, if buffered by batching, queues a
    /// `TrackIntent` for `reconcile_unconfirmed` to resolve later) and
    /// returns `(id, assigned_idx)` if accepted immediately, so batch callers
    /// can collect these and send one `Assigned` reply for the whole batch.
    fn accept_as_leader(
        &mut self,
        id: EntryId,
        entry: T,
        from: Option<NodeId>,
    ) -> Option<(EntryId, usize)> {
        // Only accept while leadership is stable (Accept phase).
        let stable_leader =
            matches!(self.op.get_current_leader(), Some((pid, true)) if pid == self.pid);
        if !stable_leader {
            return None;
        }
        let intent = match from {
            None => TrackIntent::Local(id),
            Some(from) => TrackIntent::Remote { id, from },
        };
        match self.append_tracked(intent, entry) {
            Ok(Some((after, _ballot))) => Some((id, after)),
            Ok(None) => None,
            Err(err) => {
                self.resolve_pending_failed(id, err);
                None
            }
        }
    }

    /// Matches everything buffered in `unconfirmed_local` to the index it's
    /// assigned once its batch flushes and `get_accepted_idx()` advances.
    /// FIFO correspondence is exact here regardless of what added to the
    /// shared batch buffer (see `unconfirmed_local`'s doc comment), as long as
    /// the ballot hasn't changed since the entry was buffered; if it has,
    /// leadership moved on and this index may belong to different writes, so
    /// we drop tracking for it and let the caller time out.
    fn reconcile_unconfirmed(&mut self) {
        let cur_ballot = self.op.get_promise();
        let accepted = self.op.get_accepted_idx();
        let mut idx = self.last_seen_accepted_idx;
        // Entries from a single remote TaggedProposal batch can resolve
        // across several different `idx` values here (their own batch may
        // have been interleaved with others' writes); group by origin so
        // each gets one `Assigned` reply instead of one message per entry.
        let mut remote_assigned: HashMap<NodeId, Vec<(EntryId, usize)>> = HashMap::new();
        while idx < accepted {
            idx += 1;
            let Some((intent, ballot)) = self.unconfirmed_local.pop_front() else {
                break;
            };
            if ballot != cur_ballot {
                // Leadership moved on since this was buffered; the index may
                // belong to different writes. Drop tracking -- Local/Remote
                // origins simply time out, matching the ballot-mismatch
                // handling in `drain_notifiers` for already-assigned entries.
                continue;
            }
            match intent {
                TrackIntent::Untracked => {}
                TrackIntent::Local(id) => self.record_assignment(id, idx, ballot),
                TrackIntent::Remote { id, from } => {
                    remote_assigned.entry(from).or_default().push((id, idx));
                }
            }
        }
        self.last_seen_accepted_idx = accepted;

        for (from, entries) in remote_assigned {
            self.enqueue_outgoing(Message::AsyncRuntime(AsyncRuntimeMessage {
                from: self.pid,
                to: from,
                msg: AsyncRuntimeMsg::Assigned {
                    ballot: cur_ballot,
                    entries,
                },
            }));
        }
    }

    /// Attempt to dispatch every pending entry that hasn't yet been sent or
    /// accepted locally. Called from `Command::AppendNotify` and on each tick,
    /// which lets a call issued *before* an election eventually succeed once a
    /// leader is known.
    fn try_dispatch_undispatched(&mut self) {
        let Some((leader, accepted)) = self.op.get_current_leader() else {
            return;
        };
        if leader == self.pid && !accepted {
            // We're leader but not yet in Accept phase — leave entries undispatched
            // and wait for the next tick.
            return;
        }
        let entries: Vec<(EntryId, T)> = self
            .pending
            .iter_mut()
            .filter_map(|p| p.undispatched.take().map(|entry| (p.id, entry)))
            .collect();
        if leader == self.pid {
            for (id, entry) in entries {
                self.accept_as_leader(id, entry, None);
            }
        } else if !entries.is_empty() {
            self.enqueue_outgoing(Message::AsyncRuntime(AsyncRuntimeMessage {
                from: self.pid,
                to: leader,
                msg: AsyncRuntimeMsg::TaggedProposal { entries },
            }));
        }
    }

    fn handle_runtime_msg(&mut self, arm: AsyncRuntimeMessage<T>) {
        match arm.msg {
            AsyncRuntimeMsg::TaggedProposal { entries } => {
                let cur = self.op.get_current_leader().map(|(p, _)| p);
                if cur == Some(self.pid) {
                    // Collect accepted assignments and reply to the origin with a
                    // single batched `Assigned`.
                    let from = arm.from;
                    let assigned: Vec<(EntryId, usize)> = entries
                        .into_iter()
                        .filter_map(|(id, entry)| self.accept_as_leader(id, entry, Some(from)))
                        .collect();
                    if !assigned.is_empty() {
                        let ballot = self.op.get_promise();
                        self.enqueue_outgoing(Message::AsyncRuntime(AsyncRuntimeMessage {
                            from: self.pid,
                            to: arm.from,
                            msg: AsyncRuntimeMsg::Assigned {
                                ballot,
                                entries: assigned,
                            },
                        }));
                    }
                } else if let Some(new_leader) = cur {
                    // Leadership drifted since sender chose us. Hop the whole batch
                    // forward, preserving the original `from` so the leader replies
                    // to the true origin.
                    self.enqueue_outgoing(Message::AsyncRuntime(AsyncRuntimeMessage {
                        from: arm.from,
                        to: new_leader,
                        msg: AsyncRuntimeMsg::TaggedProposal { entries },
                    }));
                }
                // Else: no leader; drop. Originators will timeout.
            }
            AsyncRuntimeMsg::Assigned { ballot, entries } => {
                for (id, assigned_idx) in entries {
                    self.record_assignment(id, assigned_idx, ballot);
                }
            }
        }
    }

    /// Given a `(batched_len, accepted_idx)` snapshot taken before some call
    /// that may have silently added to the shared batch buffer (a forwarded
    /// proposal, an incoming replication batch, a reconfiguration stopsign),
    /// pushes a `TrackIntent::Untracked` placeholder in `unconfirmed_local`
    /// for each newly-added entry, keeping its FIFO count accurate.
    ///
    /// Growth is `(accepted_after - accepted_before) + (batched_after -
    /// batched_before)`, computed with signed arithmetic and clamped at 0:
    /// `accepted_idx` can legitimately *decrease* when a follower's log is
    /// truncated by an incoming `AcceptSync` from a new leader, which isn't a
    /// case with anything new to track.
    fn track_batch_growth(&mut self, batched_before: usize, accepted_before: usize) {
        let batched_after = self.op.get_batched_len();
        let accepted_after = self.op.get_accepted_idx();
        let added = accepted_after as isize - accepted_before as isize + batched_after as isize
            - batched_before as isize;
        let ballot = self.op.get_promise();
        for _ in 0..added.max(0) {
            self.unconfirmed_local
                .push_back((TrackIntent::Untracked, ballot));
        }
    }

    /// Delivers an incoming `SequencePaxos`/BLE message to the core, tracking
    /// any entries it silently adds to the shared batch buffer -- see
    /// `track_batch_growth`.
    fn handle_incoming_tracked(&mut self, m: Message<T>) {
        let batched_before = self.op.get_batched_len();
        let accepted_before = self.op.get_accepted_idx();
        self.op.handle_incoming(m);
        self.track_batch_growth(batched_before, accepted_before);
    }

    async fn handle_command(&mut self, cmd: Command<T>) {
        match cmd {
            Command::Append { entry, reply } => {
                // Via append_tracked (not self.op.append) so a deferred write
                // still gets its unconfirmed_local placeholder, keeping FIFO
                // position exact for any append_notify entries batched alongside it.
                let res = self
                    .append_tracked(TrackIntent::Untracked, entry)
                    .map(|_| ());
                let _ = reply.send(res);
            }
            Command::AppendNotify {
                entry,
                timeout,
                reply,
            } => {
                if self.pending.len() >= self.config.max_pending_appends {
                    let _ = reply.send(Err(AppendError::TooManyOutstanding));
                    return;
                }
                let id = EntryId(uuid::Uuid::new_v4());
                let timeout = timeout.unwrap_or(self.config.append_notify_timeout);
                self.pending.push_back(Pending {
                    id,
                    undispatched: Some(entry),
                    assigned: None,
                    deadline: Instant::now() + timeout,
                    reply,
                });
                self.try_dispatch_undispatched();
            }
            Command::CurrentLeader { reply } => {
                let _ = reply.send(self.op.get_current_leader());
            }
            Command::DecidedIdx { reply } => {
                let _ = reply.send(self.op.get_decided_idx());
            }
            Command::ReadDecidedSuffix { from, reply } => {
                let _ = reply.send(self.op.read_decided_suffix(from));
            }
            Command::SubscribeDecided { from, tx } => {
                if self.decided_subscribers.len() >= self.config.max_decided_subscribers {
                    // Reject: drop `tx` without storing it, closing the
                    // subscriber's channel immediately with no entries delivered.
                    return;
                }
                let mut sub = DecidedSub { next_idx: from, tx };
                // Immediate catch-up: push whatever is already decided from `from`.
                if Self::push_to_sub(&mut self.op, &mut sub) {
                    self.decided_subscribers.push(sub);
                }
            }
            Command::Reconfigure {
                new_configuration,
                metadata,
                reply,
            } => {
                // Wrapped like handle_incoming_tracked: a stopsign accepted as
                // leader is itself an untracked addition to the shared batch buffer.
                let batched_before = self.op.get_batched_len();
                let accepted_before = self.op.get_accepted_idx();
                let res = self.op.reconfigure(new_configuration, metadata);
                self.track_batch_growth(batched_before, accepted_before);
                let _ = reply.send(res);
            }
            Command::TryBecomeLeader => {
                self.op.try_become_leader();
            }
            Command::Reconnected { pid } => {
                self.op.reconnected(pid);
            }
        }
    }
}

/// Drives the actor. Runs until all handles are dropped (both `cmd_tx` and
/// `incoming_tx` senders closed).
pub(crate) async fn run<T, B, R>(mut state: ActorState<T, B>, _rt: PhantomData<fn() -> R>)
where
    T: ActorEntry,
    B: Storage<T> + Send + 'static,
    R: AsyncRuntime,
{
    let mut tick_fut = Box::pin(R::sleep(state.config.tick_period)).fuse();
    let mut egress_fut = Box::pin(R::sleep(state.config.egress_period)).fuse();

    // async_channel::Receiver is !Unpin; keep it in a Pin<Box<...>> so the Stream
    // impl works under select_biased!.
    let cmd_rx = std::mem::replace(&mut state.cmd_rx, async_channel::bounded(1).1);
    let incoming_rx = std::mem::replace(&mut state.incoming_rx, async_channel::bounded(1).1);
    let mut cmd_rx = Box::pin(cmd_rx);
    let mut incoming_rx = Box::pin(incoming_rx);

    loop {
        select_biased! {
            _ = tick_fut => {
                state.op.tick();
                state.detect_and_emit_events().await;
                state.try_dispatch_undispatched();
                state.reconcile_unconfirmed();
                state.drain_notifiers();
                state.push_to_all_subs();
                tick_fut = Box::pin(R::sleep(state.config.tick_period)).fuse();
            }
            _ = egress_fut => {
                state.flush_outgoing();
                egress_fut = Box::pin(R::sleep(state.config.egress_period)).fuse();
            }
            in_msg = incoming_rx.next() => {
                match in_msg {
                    Some(Message::AsyncRuntime(arm)) => state.handle_runtime_msg(arm),
                    Some(m) => state.handle_incoming_tracked(m),
                    None => break,
                }
            }
            cmd = cmd_rx.next() => {
                match cmd {
                    Some(c) => state.handle_command(c).await,
                    None => break,
                }
            }
        }
    }
}

/// Drops the oldest elements of `buf` until its length is at most `cap`, preserving
/// the relative order of what remains. A no-op if `buf` is already within `cap`.
fn trim_oldest<M>(buf: &mut Vec<M>, cap: usize) {
    if buf.len() > cap {
        let excess = buf.len() - cap;
        buf.drain(..excess);
    }
}

#[cfg(test)]
mod tests {
    use super::trim_oldest;

    #[test]
    fn trim_oldest_drops_front_keeps_cap_most_recent() {
        let mut buf = vec![1, 2, 3, 4, 5];
        trim_oldest(&mut buf, 3);
        assert_eq!(buf, vec![3, 4, 5]);
    }

    #[test]
    fn trim_oldest_is_noop_when_within_cap() {
        let mut buf = vec![1, 2, 3];
        trim_oldest(&mut buf, 5);
        assert_eq!(buf, vec![1, 2, 3]);
    }

    #[test]
    fn trim_oldest_is_noop_when_exactly_at_cap() {
        let mut buf = vec![1, 2, 3];
        trim_oldest(&mut buf, 3);
        assert_eq!(buf, vec![1, 2, 3]);
    }

    #[test]
    fn trim_oldest_can_drop_everything() {
        let mut buf = vec![1, 2, 3];
        trim_oldest(&mut buf, 0);
        assert!(buf.is_empty());
    }
}

use core::time::Duration;
use std::marker::PhantomData;

use futures::channel::oneshot;

use omnipaxos::{
    messages::Message,
    storage::{Entry, Storage},
    util::{LogEntry, NodeId},
    ClusterConfig, OmniPaxos,
};

use super::{
    actor::{run, ActorConfig, ActorState},
    event::{AppendError, Command, OmniPaxosEvent, RuntimeProposeErr},
    traits::{ActorEntry, AsyncRuntime},
};

/// Configuration for the async runtime actor.
#[derive(Debug, Clone)]
pub struct RuntimeConfig {
    /// How often the actor calls `tick()` on the underlying OmniPaxos.
    /// Should match the tick timeout budget used when building `ServerConfig`.
    pub tick_period: Duration,
    /// How often outgoing messages are drained and forwarded on the `outgoing_messages`
    /// channel.
    pub egress_period: Duration,
    /// Bounded capacity for the actor's command channel.
    pub cmd_channel_capacity: usize,
    /// Bounded capacity for the outgoing message channel.
    pub outgoing_capacity: usize,
    /// Bounded capacity for the incoming message channel.
    pub incoming_capacity: usize,
    /// Bounded capacity for the event channel.
    pub event_capacity: usize,
    /// How long an `append_notify` call waits for its entry to be decided before
    /// resolving with [`AppendError::Timeout`](super::AppendError::Timeout).
    pub append_notify_timeout: Duration,
    /// Bounded capacity for each per-subscriber decided-log stream returned by
    /// [`OmniPaxosHandle::subscribe_decided`].
    pub decided_channel_capacity: usize,
    /// Maximum number of concurrently outstanding `append_notify` calls (i.e.
    /// calls that have not yet resolved). Once reached, further `append_notify`
    /// calls are rejected immediately with [`AppendError::TooManyOutstanding`]
    /// rather than queued, so a stalled cluster (e.g. no leader) can't grow this
    /// backlog without bound.
    pub max_pending_appends: usize,
    /// Maximum number of concurrent [`OmniPaxosHandle::subscribe_decided`]
    /// subscribers. Once reached, a new subscription is rejected: the returned
    /// receiver's channel is closed immediately without delivering any entries.
    pub max_decided_subscribers: usize,
    /// Fallback cap on how many outgoing messages the actor buffers internally
    /// while waiting for room on the (bounded) `outgoing_messages` channel,
    /// used only if that channel's own capacity can't be read. Past this cap,
    /// the *oldest* buffered messages are dropped rather than growing without
    /// bound -- safe because OmniPaxos already tolerates lost messages via its
    /// own resend/retry mechanisms.
    pub max_outgoing_buffered: usize,
}

impl Default for RuntimeConfig {
    fn default() -> Self {
        Self {
            tick_period: Duration::from_millis(10),
            egress_period: Duration::from_millis(1),
            cmd_channel_capacity: 1024,
            outgoing_capacity: 10_000,
            incoming_capacity: 10_000,
            event_capacity: 1024,
            append_notify_timeout: Duration::from_secs(5),
            decided_channel_capacity: 1024,
            max_pending_appends: 1024,
            max_decided_subscribers: 128,
            max_outgoing_buffered: 10_000,
        }
    }
}

/// A cloneable, `Send + Sync` handle to an OmniPaxos actor running in the background.
///
/// All state-mutating and read methods are `async`. Users must drive message transport
/// externally via [`OmniPaxosHandle::outgoing_messages`] and
/// [`OmniPaxosHandle::handle_incoming`]. Dropping every clone shuts the actor down.
pub struct OmniPaxosHandle<T>
where
    T: Entry,
{
    cmd_tx: async_channel::Sender<Command<T>>,
    events_rx: async_channel::Receiver<OmniPaxosEvent>,
    outgoing_rx: async_channel::Receiver<Message<T>>,
    incoming_tx: async_channel::Sender<Message<T>>,
    decided_channel_capacity: usize,
}

impl<T> Clone for OmniPaxosHandle<T>
where
    T: Entry,
{
    fn clone(&self) -> Self {
        Self {
            cmd_tx: self.cmd_tx.clone(),
            events_rx: self.events_rx.clone(),
            outgoing_rx: self.outgoing_rx.clone(),
            incoming_tx: self.incoming_tx.clone(),
            decided_channel_capacity: self.decided_channel_capacity,
        }
    }
}

impl<T> OmniPaxosHandle<T>
where
    T: Entry + Send + 'static,
{
    /// Append an entry and await its decided log index.
    ///
    /// Works from any node: the actor tags the entry with a unique id, routes it to
    /// the current leader, and resolves the future when the assigned log index is
    /// decided. If no leader is known yet, the call waits rather than failing fast --
    /// it resolves once a leader is elected, or with `Timeout` if none is elected in
    /// time. Fails with:
    /// - [`AppendError::Timeout`] if the entry is not decided within
    ///   [`RuntimeConfig::append_notify_timeout`] (including when no leader was ever
    ///   elected in that time);
    /// - [`AppendError::Propose`] if the underlying propose call itself failed (e.g. a
    ///   reconfiguration is already pending) -- only when this node owns the pending
    ///   call, otherwise it still resolves via `Timeout`;
    /// - [`AppendError::Superseded`] if a leader change occurred before decision --
    ///   a heuristic, not a certainty; see its doc comment for why, and check the
    ///   returned index yourself if you need to know for sure;
    /// - [`AppendError::TooManyOutstanding`] if [`RuntimeConfig::max_pending_appends`]
    ///   outstanding calls are already queued.
    ///
    /// Uses [`RuntimeConfig::append_notify_timeout`] as the deadline; use
    /// [`Self::append_notify_with_timeout`] to override it for a single call.
    pub async fn append_notify(&self, entry: T) -> Result<usize, AppendError<T>> {
        self.append_notify_inner(entry, None).await
    }

    /// Same as [`append_notify`](Self::append_notify), but `timeout` overrides
    /// [`RuntimeConfig::append_notify_timeout`] for this call only -- e.g. to give a
    /// latency-sensitive caller a shorter deadline, or a bulk/background caller a
    /// longer one, without changing the default for every other call.
    pub async fn append_notify_with_timeout(
        &self,
        entry: T,
        timeout: Duration,
    ) -> Result<usize, AppendError<T>> {
        self.append_notify_inner(entry, Some(timeout)).await
    }

    async fn append_notify_inner(
        &self,
        entry: T,
        timeout: Option<Duration>,
    ) -> Result<usize, AppendError<T>> {
        let (tx, rx) = oneshot::channel();
        self.cmd_tx
            .send(Command::AppendNotify {
                entry,
                timeout,
                reply: tx,
            })
            .await
            .map_err(|_| AppendError::Shutdown)?;
        rx.await.unwrap_or(Err(AppendError::Shutdown))
    }

    /// Append an entry without waiting for decision. Mirrors the sync API.
    pub async fn append(&self, entry: T) -> Result<(), RuntimeProposeErr<T>> {
        let (tx, rx) = oneshot::channel();
        self.cmd_tx
            .send(Command::Append { entry, reply: tx })
            .await
            .map_err(|_| RuntimeProposeErr::Shutdown)?;
        match rx.await {
            Ok(res) => res.map_err(RuntimeProposeErr::Propose),
            Err(_) => Err(RuntimeProposeErr::Shutdown),
        }
    }

    /// Ask the actor for the current leader.
    pub async fn current_leader(&self) -> Option<(NodeId, bool)> {
        let (tx, rx) = oneshot::channel();
        if self
            .cmd_tx
            .send(Command::CurrentLeader { reply: tx })
            .await
            .is_err()
        {
            return None;
        }
        rx.await.unwrap_or(None)
    }

    /// Ask the actor for the current decided index.
    pub async fn decided_idx(&self) -> usize {
        let (tx, rx) = oneshot::channel();
        if self
            .cmd_tx
            .send(Command::DecidedIdx { reply: tx })
            .await
            .is_err()
        {
            return 0;
        }
        rx.await.unwrap_or(0)
    }

    /// Ask the actor for a slice of the decided log starting at `from`.
    pub async fn read_decided_suffix(&self, from: usize) -> Option<Vec<LogEntry<T>>> {
        let (tx, rx) = oneshot::channel();
        if self
            .cmd_tx
            .send(Command::ReadDecidedSuffix { from, reply: tx })
            .await
            .is_err()
        {
            return None;
        }
        rx.await.unwrap_or(None)
    }

    /// Propose a cluster reconfiguration.
    pub async fn reconfigure(
        &self,
        new_configuration: ClusterConfig,
        metadata: Option<Vec<u8>>,
    ) -> Result<(), RuntimeProposeErr<T>> {
        let (tx, rx) = oneshot::channel();
        self.cmd_tx
            .send(Command::Reconfigure {
                new_configuration,
                metadata,
                reply: tx,
            })
            .await
            .map_err(|_| RuntimeProposeErr::Shutdown)?;
        match rx.await {
            Ok(res) => res.map_err(RuntimeProposeErr::Propose),
            Err(_) => Err(RuntimeProposeErr::Shutdown),
        }
    }

    /// Attempt to become the leader by incrementing the local ballot.
    pub async fn try_become_leader(&self) {
        let _ = self.cmd_tx.send(Command::TryBecomeLeader).await;
    }

    /// Notify the actor that a previously disconnected peer is reachable again.
    pub async fn reconnected(&self, pid: NodeId) {
        let _ = self.cmd_tx.send(Command::Reconnected { pid }).await;
    }

    /// Subscribe to state-transition events. Each event is delivered to exactly one
    /// receiver: if you clone the returned receiver, the clones share the queue.
    /// For fan-out to multiple independent subscribers, wrap in a broadcasting task.
    pub fn subscribe_events(&self) -> async_channel::Receiver<OmniPaxosEvent> {
        self.events_rx.clone()
    }

    /// Subscribe to decided log entries, starting at `from`. Returns a receiver
    /// that emits [`LogEntry`]s in log order — both the backlog already decided
    /// at subscription time and entries decided later.
    ///
    /// Each call creates an independent subscription with its own cursor;
    /// multiple subscribers can coexist, up to [`RuntimeConfig::max_decided_subscribers`]
    /// — beyond that, the returned receiver's channel is closed immediately
    /// without delivering any entries. Dropping the receiver ends the
    /// subscription; slow subscribers apply backpressure by causing the actor
    /// to defer pushes rather than blocking the actor loop.
    pub async fn subscribe_decided(&self, from: usize) -> async_channel::Receiver<LogEntry<T>> {
        let (tx, rx) = async_channel::bounded(self.decided_channel_capacity);
        // If the actor is gone, `rx` stays open but never receives — the
        // caller's stream drops naturally when the sender is dropped here.
        let _ = self
            .cmd_tx
            .send(Command::SubscribeDecided { from, tx })
            .await;
        rx
    }

    /// Returns a receiver from which outgoing messages should be drained and forwarded
    /// by the application's transport.
    pub fn outgoing_messages(&self) -> async_channel::Receiver<Message<T>> {
        self.outgoing_rx.clone()
    }

    /// Deliver an incoming message from the network to the actor.
    pub async fn handle_incoming(&self, m: Message<T>) {
        let _ = self.incoming_tx.send(m).await;
    }
}

/// Spawn the actor and return a handle to it.
pub fn spawn_actor<T, B, R>(op: OmniPaxos<T, B>, cfg: RuntimeConfig) -> OmniPaxosHandle<T>
where
    T: ActorEntry,
    B: Storage<T> + Send + 'static,
    R: AsyncRuntime,
{
    let (cmd_tx, cmd_rx) = async_channel::bounded(cfg.cmd_channel_capacity);
    let (outgoing_tx, outgoing_rx) = async_channel::bounded(cfg.outgoing_capacity);
    let (incoming_tx, incoming_rx) = async_channel::bounded(cfg.incoming_capacity);
    let (event_tx, events_rx) = async_channel::bounded(cfg.event_capacity);

    let state = ActorState::new(
        op,
        cmd_rx,
        incoming_rx,
        outgoing_tx,
        event_tx,
        ActorConfig::from(&cfg),
    );

    R::spawn(run::<T, B, R>(state, PhantomData::<fn() -> R>));

    OmniPaxosHandle {
        cmd_tx,
        events_rx,
        outgoing_rx,
        incoming_tx,
        decided_channel_capacity: cfg.decided_channel_capacity,
    }
}
use core::time::Duration;

use futures::channel::oneshot;

use omnipaxos::{
    storage::Entry,
    util::{LogEntry, NodeId},
    ClusterConfig, ProposeErr,
};

/// A state transition observed by the actor and broadcast on the event stream.
#[derive(Debug, Clone)]
pub enum OmniPaxosEvent {
    /// A new leader was observed on this node.
    LeaderElected {
        /// The pid of the elected leader.
        pid: NodeId,
        /// Whether this node's phase is `Phase::Accept`.
        accepted: bool,
    },
    /// The decided index advanced. The value is the new decided index.
    Decided {
        /// The new decided index.
        new_decided_idx: usize,
    },
    /// A reconfiguration StopSign was decided.
    Reconfigured {
        /// The log index at which the StopSign was decided.
        stop_sign_idx: usize,
    },
}

/// Error returned by [`OmniPaxosHandle::append_notify`](super::OmniPaxosHandle::append_notify).
#[derive(Debug)]
pub enum AppendError<T>
where
    T: Entry,
{
    /// The underlying [`OmniPaxos::append`](omnipaxos::OmniPaxos::append) call failed while
    /// this node was accepting the entry as leader (e.g. a reconfiguration is already
    /// pending). Unlike the other variants, this is resolved immediately rather than
    /// waiting for `append_notify_timeout` -- but only when this node itself owns the
    /// pending call (i.e. it originated the `append_notify` or was routed to it as
    /// leader). If the failure happens on a different node than the origin, the origin
    /// still just sees a `Timeout`, since surfacing the specific error cross-node would
    /// require a new wire message.
    Propose(ProposeErr<T>),
    /// A leader change occurred after the entry was accepted at the given index but
    /// before it was decided. This is a *heuristic*, not a certainty: a new leader is
    /// required to adopt any value a majority-overlapping quorum may have already
    /// accepted, so the entry can still end up decided at `log_entry_idx` under the
    /// new ballot -- we just stop waiting rather than confirm it. Check
    /// [`OmniPaxosHandle::read_decided_suffix`](super::OmniPaxosHandle::read_decided_suffix)
    /// at that index if you need to know for sure before re-appending.
    Superseded {
        /// The log index the entry was assigned before the leader change.
        log_entry_idx: usize,
    },
    /// The `append_notify_timeout` elapsed before the entry was decided. Retry safe.
    Timeout,
    /// The actor has shut down before the entry could be decided.
    Shutdown,
    /// The actor already has [`RuntimeConfig::max_pending_appends`](super::RuntimeConfig::max_pending_appends)
    /// outstanding `append_notify` calls; this one was rejected immediately rather
    /// than queued. Nothing was proposed, so it's safe to retry (ideally after a
    /// backoff, since the backlog needs time to drain).
    TooManyOutstanding,
}

/// Error returned by [`OmniPaxosHandle::append`](super::OmniPaxosHandle::append) and
/// [`OmniPaxosHandle::reconfigure`](super::OmniPaxosHandle::reconfigure). Distinct from
/// [`AppendError`]: these calls don't track decision, so they only ever fail
/// synchronously -- either the propose call itself was rejected, or the actor is gone.
#[derive(Debug)]
pub enum RuntimeProposeErr<T>
where
    T: Entry,
{
    /// The underlying propose call failed (e.g. a reconfiguration is already pending,
    /// or an invalid cluster config was proposed).
    Propose(ProposeErr<T>),
    /// The actor has shut down.
    Shutdown,
}

/// Commands sent from an [`OmniPaxosHandle`](super::OmniPaxosHandle) to the actor task.
///
/// This type is `pub(crate)` because it is an implementation detail of the actor <-> handle
/// protocol.
pub(crate) enum Command<T>
where
    T: Entry,
{
    Append {
        entry: T,
        reply: oneshot::Sender<Result<(), ProposeErr<T>>>,
    },
    AppendNotify {
        entry: T,
        /// Overrides [`RuntimeConfig::append_notify_timeout`](super::RuntimeConfig::append_notify_timeout)
        /// for this call only, if `Some`.
        timeout: Option<Duration>,
        reply: oneshot::Sender<Result<usize, AppendError<T>>>,
    },
    CurrentLeader {
        reply: oneshot::Sender<Option<(NodeId, bool)>>,
    },
    DecidedIdx {
        reply: oneshot::Sender<usize>,
    },
    ReadDecidedSuffix {
        from: usize,
        reply: oneshot::Sender<Option<Vec<LogEntry<T>>>>,
    },
    SubscribeDecided {
        from: usize,
        tx: async_channel::Sender<LogEntry<T>>,
    },
    Reconfigure {
        new_configuration: ClusterConfig,
        metadata: Option<Vec<u8>>,
        reply: oneshot::Sender<Result<(), ProposeErr<T>>>,
    },
    TryBecomeLeader,
    Reconnected {
        pid: NodeId,
    },
}
//! Async runtime actor layer for OmniPaxos.
//!
//! The [`AsyncRuntime`] trait abstracts over the async executor so this crate can be used
//! on top of any runtime. A ready-to-use [`TokioRuntime`] is provided behind the
//! `tokio_runtime` feature.
//!
//! The main entry point is [`spawn_actor`], which takes an
//! [`OmniPaxos`](omnipaxos::OmniPaxos) instance and returns an [`OmniPaxosHandle`]. The
//! handle is cloneable and provides `async` methods to append entries and observe state
//! transitions.
//!
//! The runtime does NOT own message transport: use [`OmniPaxosHandle::outgoing_messages`]
//! to drain outgoing messages and [`OmniPaxosHandle::handle_incoming`] to deliver
//! incoming ones. This keeps the crate free of I/O dependencies and lets users plug in
//! any transport (TCP, QUIC, in-process channels, etc.).

#![deny(missing_docs)]

mod actor;
mod event;
mod handle;
mod traits;

#[cfg(feature = "tokio_runtime")]
mod tokio_rt;

pub use event::{AppendError, OmniPaxosEvent, RuntimeProposeErr};
pub use handle::{spawn_actor, OmniPaxosHandle, RuntimeConfig};
pub use omnipaxos::messages::EntryId;
pub use traits::{ActorEntry, AsyncRuntime};

#[cfg(feature = "tokio_runtime")]
pub use tokio_rt::TokioRuntime;
use core::{future::Future, time::Duration};

use omnipaxos::storage::Entry;

/// A blanket trait that fixes all the `Send` bounds an [`Entry`] must satisfy to cross
/// the actor boundary. Users normally do not implement this manually — a blanket impl
/// covers any `Entry` whose associated types are `Send`.
#[cfg(not(feature = "unicache"))]
pub trait ActorEntry: Entry<Snapshot: Send> + Send + 'static {}

#[cfg(not(feature = "unicache"))]
impl<T> ActorEntry for T where T: Entry<Snapshot: Send> + Send + 'static {}

/// A blanket trait that fixes all the `Send` bounds an [`Entry`] must satisfy to cross
/// the actor boundary. Users normally do not implement this manually — a blanket impl
/// covers any `Entry` whose associated types are `Send`.
#[cfg(feature = "unicache")]
pub trait ActorEntry:
    Entry<Snapshot: Send, UniCache: Send, EncodeResult: Send> + Send + 'static
{
}

#[cfg(feature = "unicache")]
impl<T> ActorEntry for T where
    T: Entry<Snapshot: Send, UniCache: Send, EncodeResult: Send> + Send + 'static
{
}

/// Abstraction over an async executor.
///
/// Implement this trait to run OmniPaxos on runtimes other than tokio. Two primitives
/// are required: task spawning and a timer. The actor loop builds intervals on top of
/// [`AsyncRuntime::sleep`], so no separate `interval` primitive is needed.
pub trait AsyncRuntime: 'static {
    /// The join handle returned by [`AsyncRuntime::spawn`]. The runtime is free to
    /// return `()` if it does not need cancellation or joining.
    type JoinHandle: Send + 'static;

    /// Spawn a future onto the executor.
    fn spawn<F>(future: F) -> Self::JoinHandle
    where
        F: Future<Output = ()> + Send + 'static;

    /// Return a future that resolves after `duration` elapses.
    fn sleep(duration: Duration) -> impl Future<Output = ()> + Send + 'static;
}

//! Integration tests for the async runtime layer.
//!
//! Sets up a small in-process cluster where each node runs an OmniPaxos actor and messages
//! are shuttled between them over in-memory channels, then exercises the async API.
